mapper.update:
UPDATE order_route
SET status = #{status}
WHERE order_id = #{orderId}
  AND seq = #{seq}

mapper.select:
SELECT *
FROM order_route
WHERE order_id = #{orderId}
  AND seq = #{seq}

mapper.update:
UPDATE order_route
SET arrive_trip_no = #{tripNo}
WHERE order_id = #{orderId}
  AND seq = #{seq}
  AND status = 'PENDING'

UPDATE order_route
SET postman_id = #{postmanId}
WHERE order_id = #{orderId}
  AND seq = #{seq}

UPDATE order_route
SET depart_time = #{now}
WHERE order_id = #{orderId}
  AND seq = #{seq}
  AND depart_time IS NULL

UPDATE order_route
SET status             = 'ARRIVED',
    actual_arrive_time = #{now}
WHERE order_id = #{orderId}
  AND seq = #{seq}
  AND status = 'PENDING'

UPDATE order_route
SET status = #{status},
    remark = #{remark}
WHERE order_id = #{orderId}
  AND seq = #{seq}
  AND status = 'DELIVERING'

UPDATE order_route
SET status      = 'ARRIVED',
    depart_time = NULL,
    postman_id  = NULL,
    remark      = #{remark}
WHERE order_id = #{orderId}
  AND seq = #{seq}
  AND status = 'DELIVERING'
